import importlib
orig = importlib.import_module("orig")
new = importlib.import_module("new")

VIABLE = {"status": "active", "tier": "basic", "amount": 40, "method": "card"}
TYPES = [None, "x", 5, [], {}, {"id":"a"}, {"id":"a","status":"active"}, {"id":"a","status":"active","tier":"basic"}]

cases = []
# malformed / non-dict
for m in TYPES:
    for p in [None, 5, "x", []]:
        cases.append((m, p))

def mem(**over):
    base = dict(VIABLE)
    base.update(over)
    return base

def pay(**over):
    base = {"amount": 40, "method": "card"}
    base.update(over)
    return base

# built on a viable member
statuses = ["active", "lapsed", "suspended", "banned", "weird", "ACTIVE", ""]
for s in statuses:
    for t in [None, "basic", "gold", "platinum", "BASIC", 3]:
        for amt in [None, "40", -5, 0, 1, 39, 40, 41, 50, 100, 10**9]:
            for meth in [None, "card", "transfer", "check", "CARD", 7]:
                for ed in [None, -1, 0, 30, 31, 100, "30"]:
                    for st in [None, -1, 0, 2, 3, 5, "3"]:
                        for ident in ["abc", ""]:
                            m = mem(status=s, tier=t, expired_days=ed, strikes=st, id=ident)
                            p = pay(amount=amt, method=meth)
                            cases.append((m, p))

# missing fields variations
for m in [mem(), mem(id=None), mem(status=None), mem(tier=None),
          {"id":"a","status":"active"}, {"id":"a","tier":"basic"}, {"status":"active","tier":"basic"},
          {"id":"","status":"active","tier":"basic"}]:
    for p in [pay(), pay(amount=None), pay(method=None), {"amount":40}, {"method":"card"}, {}]:
        cases.append((m, p))

mismatch = 0
for i,(m,p) in enumerate(cases):
    a = orig.process_renewal(m, p)
    b = new.process_renewal(m, p)
    if a != b:
        mismatch += 1
        if mismatch <= 20:
            print("MISMATCH", repr(m), repr(p), "orig=", a, "new=", b)
print("total cases:", len(cases), "mismatches:", mismatch)
